'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',
 box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4Z M3 7l9 4 9-4 M12 11v10 M7 5l10 4"/>',
 layers:'<path d="m3 7 9-4 9 4-9 4Z M3 12l9 4 9-4 M3 17l9 4 9-4"/>',
 orders:'<path d="M8 4H5v17h14V4h-3 M9 2h6v4H9Z M8 11h8 M8 15h8"/>',
 flow:'<rect x="3" y="4" width="4" height="16"/><rect x="10" y="4" width="4" height="10"/><rect x="17" y="4" width="4" height="13"/>',
 alert:'<path d="m12 3 10 18H2Z M12 9v5 M12 17v1"/>',
 chart:'<path d="M3 3v18h18 M7 16v-5 M12 16V6 M17 16V9"/>',
 settings:'<path d="M4 6h16 M4 12h16 M4 18h16"/><rect x="7" y="4" width="3" height="4"/><rect x="14" y="10" width="3" height="4"/><rect x="8" y="16" width="3" height="4"/>',
 book:'<path d="M12 5v16 M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-6-2-10 1Z"/>',
 plus:'<path d="M12 5v14 M5 12h14"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
 down:'<path d="M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5"/>',
 arrow:'<path d="M4 12h16 m-6-6 6 6-6 6"/>',
 bell:'<path d="M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3Z M10 21h4"/>',
 factory:'<path d="M3 21V10l6 3V8l6 4V3h4l2 18Z M6 17h2 M11 17h2 M16 17h2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
 edit:'<path d="m14 5 5 5 M3 21l5-1L21 7l-5-5L3 15Z"/>',
 shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z m-5 10 4 4 6-7"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="square" stroke-linejoin="miter" aria-hidden="true">${icons[name] || icons.box}</svg>`;
const states = ['Pendiente','En producción','Control de calidad','Terminado','Despachado'];
const routes = {dashboard:['Vista general','grid'],orders:['Órdenes de producción','orders'],tracking:['Seguimiento','flow'],products:['Productos','box'],materials:['Materiales','layers'],incidents:['Incidencias','alert'],reports:['Reportes','chart'],project:['Proyecto y piloto','book'],settings:['Datos y respaldo','settings'],guide:['Guía de uso','book']};
const KEY = 'sigcp-manaco-v1';
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'America/La_Paz',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const date = value => value ? new Intl.DateTimeFormat('es-BO',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value.length===10 ? value+'T12:00:00' : value)) : '—';
const num = value => new Intl.NumberFormat('es-BO',{maximumFractionDigits:2}).format(value);
const shiftDate = n => {const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);};
function seed(){
 const materials=[{id:'MAT-001',name:'Cuero bovino negro',unit:'m²',stock:420,min:100},{id:'MAT-002',name:'Suelas de caucho',unit:'pares',stock:1800,min:400},{id:'MAT-003',name:'Adhesivo industrial',unit:'litros',stock:18,min:30},{id:'MAT-004',name:'Plantillas anatómicas',unit:'pares',stock:320,min:400},{id:'MAT-005',name:'Cuero bovino café',unit:'m²',stock:285,min:80},{id:'MAT-006',name:'Textil técnico azul',unit:'m²',stock:510,min:100}];
 const products=[{id:'PRD-001',name:'Clásico ejecutivo',category:'Formal',sizes:'38, 39, 40, 41, 42',color:'Negro',description:'Calzado de cuero con acabado liso y suela de caucho.',tone:'#263344',bom:[{material:'MAT-001',qty:.2},{material:'MAT-002',qty:1},{material:'MAT-003',qty:.03}]},{id:'PRD-002',name:'Urban casual',category:'Casual',sizes:'36, 37, 38, 39, 40, 41, 42',color:'Café',description:'Diseño versátil de cuero para uso diario.',tone:'#98745a',bom:[{material:'MAT-005',qty:.18},{material:'MAT-002',qty:1}]},{id:'PRD-003',name:'Sport active',category:'Deportivo',sizes:'35, 36, 37, 38, 39, 40, 41',color:'Azul',description:'Construcción ligera en textil con plantilla anatómica.',tone:'#365b83',bom:[{material:'MAT-006',qty:.25},{material:'MAT-004',qty:1}]},{id:'PRD-004',name:'Escolar clásico',category:'Escolar',sizes:'30, 31, 32, 33, 34, 35, 36',color:'Negro',description:'Resistencia y comodidad para la jornada escolar.',tone:'#3d424b',bom:[{material:'MAT-001',qty:.15},{material:'MAT-002',qty:1}]}];
 const spec=[['PRD-001',240,1,4,'Alta','María Vargas','40'],['PRD-002',180,2,2,'Normal','Carlos Rojas','39'],['PRD-003',320,0,7,'Alta','Ana Mendoza','38'],['PRD-004',150,1,5,'Normal','Luis Flores','34'],['PRD-001',200,3,-1,'Normal','María Vargas','41'],['PRD-002',160,4,-2,'Normal','Carlos Rojas','40'],['PRD-003',120,0,9,'Normal','Ana Mendoza','39'],['PRD-004',280,2,3,'Alta','Luis Flores','35']];
 const orders=spec.map((s,i)=>({id:'OP-'+String(1041+i),product:s[0],quantity:s[1],state:s[2],due:shiftDate(s[3]),priority:s[4],owner:s[5],size:s[6],start:shiftDate(-7+i%4),created:shiftDate(-7+i%4),closed:s[2]>=3?shiftDate(-3):'',evidence:s[2]>=3?'Lote de demostración verificado.':'',consumed:s[2]>0,history:[{at:new Date(shiftDate(-7+i%4)+'T12:00:00').toISOString(),text:'Orden de demostración registrada',actor:'Área de producción'}]}));
 return {version:1,mode:'demo',products,materials,orders,incidents:[{id:'INC-001',order:'OP-1041',type:'Falla de máquina',severity:'Alta',description:'Revisar tensión de la máquina de costura en línea 02.',owner:'Luis Flores',status:'Abierta',created:shiftDate(-1),closed:'',action:''},{id:'INC-002',order:'OP-1043',type:'Falta de material',severity:'Media',description:'Verificar disponibilidad de plantillas antes de liberar el lote.',owner:'Ana Mendoza',status:'En atención',created:today(),closed:'',action:'Solicitud de reposición en revisión.'}],audit:[{at:new Date().toISOString(),text:'Entorno de demostración iniciado',actor:'Área de producción'}],movements:[],pilot:{}};
}
let db, storageIssue=false, unreadableData='';
try{unreadableData=localStorage.getItem(KEY)||'';db=unreadableData?JSON.parse(unreadableData):seed();validateBackup(db);unreadableData='';}catch{db=seed();storageIssue=true;}
let route='dashboard', query='', statusFilter='', reportFrom='', reportTo='', toastTimer;
function persist(message){if(storageIssue){toast('El almacenamiento necesita revisión. Consulta Datos y respaldo.');return false;}try{localStorage.setItem(KEY,JSON.stringify(db));if(message)toast(message);return true;}catch{toast('No se pudo guardar. Exporta un respaldo antes de cerrar.');return false;}}
function log(text){db.audit.unshift({at:new Date().toISOString(),text,actor:'Área de producción'});}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),4500);}
const product = id => db.products.find(p=>p.id===id);
const lowStock = () => db.materials.filter(m=>m.stock<=m.min);
const openIncidents = () => db.incidents.filter(i=>i.status!=='Resuelta');
const badge = s => `<span class="tag s${s}">${states[s]}</span>`;
const priority = p => `<span class="priority ${p==='Alta'?'':'normal'}"><i></i>${esc(p)}</span>`;
const button = (label,action,ico='plus',style='primary') => `<button class="btn ${style}" data-action="${action}">${icon(ico)}${label}</button>`;
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">PRODUCCIÓN / ${esc(route==='dashboard'?'CENTRO DE CONTROL':routes[route][0].toUpperCase())}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function kpi(label,value,unit,foot,ico,alert=false){return `<article class="kpi ${alert?'alert':''}"><div class="kpi-head">${label}<span class="kpi-icon">${icon(ico)}</span></div><div class="kpi-value">${value}<small>${unit}</small></div><div class="kpi-foot">${foot}</div></article>`;}
function render(){
 route=location.hash.slice(1).split('?')[0] || 'dashboard';if(!routes[route])route='dashboard';
 $('#breadcrumb').textContent=routes[route][0];document.title=routes[route][0]+' · MANACO';
 $('.pilot-label').innerHTML='<span class="live-dot"></span> '+(db.mode==='demo'?'ENTORNO DE DEMOSTRACIÓN':'REGISTROS LOCALES');
 $('.local-status').innerHTML='<i></i> '+(storageIssue?'Revisar almacenamiento':'Guardado local');
 $('#navigation').innerHTML=Object.entries(routes).filter(([key])=>key!=='guide').map(([key,[label,ico]])=>`<a href="#${key}" class="${route===key?'active ':''}${key==='project'?'nav-separator':''}" ${route===key?'aria-current="page"':''}>${icon(ico)}${label}${key==='incidents'&&openIncidents().length?`<span class="nav-count">${openIncidents().length}</span>`:''}</a>`).join('');
 $('#main').innerHTML=({dashboard:dashboard,orders:ordersView,tracking:trackingView,products:productsView,materials:materialsView,incidents:incidentsView,reports:reportsView,project:projectView,settings:settingsView,guide:guideView}[route])();
 if(storageIssue)$('#main').insertAdjacentHTML('afterbegin','<div class="note danger">Los datos guardados no se pudieron leer. Se muestran ejemplos temporales sin sobrescribir el original. <button class="text-link" data-action="recover-raw">Descargar datos originales</button>. Después puedes restaurar un respaldo desde Datos y respaldo.</div>');
 $('#main').classList.remove('view-enter');void $('#main').offsetWidth;$('#main').classList.add('view-enter');
}
function dashboard(){
 const active=db.orders.filter(o=>o.state<3),done=db.orders.filter(o=>o.state>=3),total=db.orders.reduce((a,o)=>a+o.quantity,0),finished=done.reduce((a,o)=>a+o.quantity,0);
 return heading('Vista general','Cada etapa conectada. Cada decisión, con información.',button('Exportar reporte','export-orders','down','')+button('Nueva orden','new-order'))+
 `<section class="overview-banner"><div><div class="eyebrow">GESTIÓN INDUSTRIAL DE CALZADO</div><h2>El pulso de tu producción.</h2><p>Supervisa órdenes, anticipa faltantes y mantén el trabajo en movimiento.</p></div><div class="banner-side"><div class="banner-date"><span>COCHABAMBA, BOLIVIA</span><strong>${date(today())}</strong></div><svg class="factory-art" viewBox="0 0 120 90" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M4 78h111M13 75V37l25 13V30l27 16V13h12l6 62M13 75h94V39L83 50M65 13h12M65 20h13M23 59h8v9h-8zM43 59h8v9h-8zM64 59h8v9h-8zM89 59h8v9h-8zM17 85h90"/><path d="M69 7V3m8 3 3-3"/></svg></div></section>`+
 `<section class="kpis" aria-label="Indicadores de producción">${kpi('Órdenes activas',num(active.length),'órdenes',`<b>${db.orders.filter(o=>o.state===1).length} en producción</b> · ${db.orders.filter(o=>o.state===0).length} pendientes`,'orders')}${kpi('Producción finalizada',num(finished),'pares',`${num(total)} pares planificados en total`,'box')}${kpi('Avance del plan',total?Math.round(finished/total*100)+'%':'—','',`${done.length} de ${db.orders.length} órdenes terminadas`,'chart')}${kpi('Requieren atención',lowStock().length+openIncidents().length,'alertas',`<b>${lowStock().length} materiales bajo mínimo</b> · ${openIncidents().length} incidencias`,'alert',true)}</section>`+
 `<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Producción por modelo</h2><p class="panel-subtitle">Volumen planificado y finalizado · pares</p></div><div class="chart-legend"><span><i class="key"></i>Planificado</span><span><i class="key red"></i>Finalizado</span></div></div>${productionChart()}<div class="chart-bottom"><span>${db.mode==='demo'?'Datos de demostración':'Registros locales'} · Todas las órdenes</span><a class="text-link" href="#reports">Ver análisis ${icon('arrow')}</a></div></section><section class="panel"><div class="panel-head"><div><h2>Centro de atención</h2><p class="panel-subtitle">Lo que necesita una decisión</p></div><span class="tag danger">${lowStock().length+openIncidents().length} alertas</span></div><div class="alert-list">${alertsHTML()}</div><div class="panel-foot"><span>Anticiparse también es producir.</span><a class="text-link" href="#incidents">Ver incidencias →</a></div></section></div>`+
 `<section class="panel"><div class="panel-head table-heading"><div><h2>Órdenes de producción</h2><p class="panel-subtitle">Seguimiento de los lotes más recientes</p></div><a class="text-link" href="#orders">Ver todas las órdenes →</a></div>${orderTable([...db.orders].reverse().slice(0,5))}</section>`;
}
function productionChart(){const rows=db.products.slice(0,6).map(p=>({name:p.name.split(' ')[0],plan:db.orders.filter(o=>o.product===p.id).reduce((a,o)=>a+o.quantity,0),done:db.orders.filter(o=>o.product===p.id&&o.state>=3).reduce((a,o)=>a+o.quantity,0)}));const max=Math.max(100,...rows.map(r=>r.plan));return `<div class="chart" role="img" aria-label="${esc(rows.map(r=>r.name+': '+r.plan+' planificados, '+r.done+' finalizados').join('. '))}"><div class="axis"><span>${num(max)}</span><span>${num(Math.round(max*2/3))}</span><span>${num(Math.round(max/3))}</span><span>0</span></div><div class="bar-area">${rows.map(r=>`<div class="bar-column" title="${esc(r.name)}: ${r.plan} planificados / ${r.done} finalizados"><div class="bar" style="--height:${r.plan/max*100}%"></div><div class="bar actual" style="--height:${r.done/max*100}%"></div><span class="bar-label">${esc(r.name)}</span></div>`).join('')}</div></div>`;}
function alertsHTML(){const items=[...lowStock().map(m=>({title:m.name,text:`${num(m.stock)} ${m.unit} disponibles · mínimo ${num(m.min)}`,link:'materials',label:'Revisar existencias'})),...openIncidents().map(i=>({title:i.type,text:i.order+' · '+i.status,link:'incidents',label:'Revisar incidencia'}))].slice(0,3);return items.length?items.map(a=>`<div class="alert-item"><div class="alert-icon">${icon('alert')}</div><div><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p><a class="text-link" href="#${a.link}">${a.label} →</a></div></div>`).join(''):'<div class="empty">Sin alertas pendientes.</div>';}
function orderTable(orders){return `<div class="table-wrap"><table><thead><tr><th>ORDEN / PRODUCTO</th><th>CANTIDAD</th><th>ESTADO</th><th>AVANCE</th><th>ENTREGA</th><th>PRIORIDAD</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><button class="order-id" data-action="detail" data-id="${o.id}">${o.id}</button><small>${esc(product(o.product)?.name)} · T${esc(o.size)}</small></td><td><strong>${num(o.quantity)}</strong> pares</td><td>${badge(o.state)}</td><td><span class="progress"><span style="width:${o.state*25}%"></span></span><span class="progress-num">${o.state*25}%</span></td><td>${date(o.due)}${o.due<today()&&o.state<3?'<small style="color:var(--red)">Entrega vencida</small>':''}</td><td>${priority(o.priority)}</td><td><button class="icon-button" data-action="detail" data-id="${o.id}" aria-label="Ver ${o.id}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No hay órdenes para esta búsqueda.</div></td></tr>'}</tbody></table></div>`;}
function toolbar(placeholder,options=[]){return `<div class="toolbar"><label class="search-box">${icon('search')}<input id="search" type="search" value="${esc(query)}" placeholder="${placeholder}" aria-label="${placeholder}"></label><div class="filters">${options.length?`<select id="status-filter" aria-label="Filtrar registros"><option value="">Todos los registros</option>${options.map((v,i)=>`<option value="${esc(v)}" ${statusFilter===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:''}<span class="result-count" id="result-count"></span></div></div>`;}
const matches = (...values) => values.join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase());
function filteredOrders(){return db.orders.filter(o=>matches(o.id,product(o.product)?.name,o.owner,o.size)&&(!statusFilter||states[o.state]===statusFilter));}
function ordersView(){return heading('Órdenes de producción','Planifica lotes, asigna responsables y controla cada entrega.',button('Exportar CSV','export-orders','down','')+button('Nueva orden','new-order'))+toolbar('Buscar orden, producto o responsable…',states)+`<section class="panel" id="results">${orderTable(filteredOrders())}</section>`;}
function trackingView(){return heading('Seguimiento de producción','De la planificación al despacho, con un historial en cada etapa.',button('Nueva orden','new-order'))+`<div class="note">El inicio de producción descuenta los materiales de la receta. Para terminar una orden, resuelve sus incidencias y registra la evidencia de control de calidad.</div><div class="kanban">${states.map((s,index)=>`<section class="kanban-column"><div class="kanban-header">${s}<span>${db.orders.filter(o=>o.state===index).length.toString().padStart(2,'0')}</span></div>${db.orders.filter(o=>o.state===index).map(o=>`<article class="kanban-card"><div class="kanban-meta"><button class="order-id" data-action="detail" data-id="${o.id}">${o.id}</button>${priority(o.priority)}</div><h3>${esc(product(o.product)?.name)}</h3><p>${num(o.quantity)} pares · Talla ${esc(o.size)}</p><div class="kanban-meta"><span>${esc(o.owner)}</span><span>${date(o.due)}</span></div><button class="btn small" data-action="detail" data-id="${o.id}">Ver orden ${icon('arrow')}</button></article>`).join('')||'<div class="empty">Sin órdenes</div>'}</section>`).join('')}</div>`;}
function shoe(tone){return `<svg class="shoe" viewBox="0 0 280 150" aria-hidden="true"><path d="M33 94c9-6 16-34 20-49l30 17 35-8 37 27c18 9 34 13 59 16 20 3 35 11 36 23H33Z" fill="${tone}"/><path d="m53 45 30 17 35-8-15 19-29 4Z" fill="#fff" opacity=".15"/><path d="M33 112c54 7 143 10 217 2v14c-54 10-151 6-217-1Z" fill="#fdfdfd" stroke="#b6bec8" stroke-width="1.5"/><path d="M35 128c60 9 150 12 213 0" stroke="#9ba6b3" stroke-width="4"/><path d="m111 69 22-3 m-14 10 22-3 m-13 10 22-3 m-12 10 21-3" stroke="#e7e8e7" stroke-width="3"/><path d="M62 76c-6 13-10 22-12 30m114-13c-8 4-12 11-12 19" stroke="#fff" opacity=".25" fill="none"/><path d="M43 117h190" stroke="#d0d7dd" stroke-dasharray="3 4"/></svg>`;}
function productCards(){const list=db.products.filter(p=>matches(p.id,p.name,p.category,p.color)&&(!statusFilter||p.category===statusFilter));return list.map(p=>`<article class="product-card"><div class="product-art"><span class="product-code">${p.id} / COLECCIÓN MANACO</span>${shoe(p.tone)}</div><div class="product-body"><span class="eyebrow">${esc(p.category)} / ${esc(p.color)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><p>Tallas ${esc(p.sizes)}<br>${p.bom.length} materiales en la receta</p><div class="product-footer"><span class="result-count">${db.orders.filter(o=>o.product===p.id).length} órdenes registradas</span><button class="text-link" data-action="edit-product" data-id="${p.id}">Editar producto →</button></div></div></article>`).join('')||'<div class="empty">No se encontraron productos.</div>';}
function productsView(){return heading('Catálogo de productos','Modelos, tallas y recetas de materiales en un solo lugar.',button('Nuevo producto','new-product'))+toolbar('Buscar modelo, código o color…',['Formal','Casual','Deportivo','Escolar','Industrial'])+`<div class="product-grid" id="results">${productCards()}</div>`;}
function materialsTable(){const list=db.materials.filter(m=>matches(m.id,m.name)&&(!statusFilter||(statusFilter==='Bajo mínimo'?m.stock<=m.min:m.stock>m.min)));return `<div class="table-wrap"><table><thead><tr><th>MATERIAL</th><th>EXISTENCIAS</th><th>NIVEL MÍNIMO</th><th>UNIDAD</th><th>DISPONIBILIDAD</th><th>ACCIONES</th></tr></thead><tbody>${list.map(m=>`<tr><td><strong>${esc(m.name)}</strong><small>${m.id}</small></td><td>${num(m.stock)}<div class="stock-track ${m.stock<=m.min?'low':''}"><span style="width:${Math.min(100,m.stock/Math.max(1,m.min*3)*100)}%"></span></div></td><td>${num(m.min)}</td><td>${esc(m.unit)}</td><td><span class="tag ${m.stock<=m.min?'danger':'s3'}">${m.stock<=m.min?'Bajo mínimo':'Disponible'}</span></td><td><div class="row-actions"><button class="btn small" data-action="stock" data-id="${m.id}">Movimiento</button><button class="icon-button" data-action="edit-material" data-id="${m.id}" aria-label="Editar ${esc(m.name)}">${icon('edit')}</button></div></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No hay materiales para esta búsqueda.</div></td></tr>'}</tbody></table></div>`;}
function materialsView(){return heading('Control de materiales','Existencias visibles para una producción sin interrupciones.',button('Exportar CSV','export-materials','down','')+button('Nuevo material','new-material'))+`<div class="kpis">${kpi('Materiales registrados',db.materials.length,'referencias','Catálogo de insumos y componentes','layers')}${kpi('Bajo nivel mínimo',lowStock().length,'materiales','Revisión de reposición necesaria','alert',true)}${kpi('Con disponibilidad',db.materials.length-lowStock().length,'materiales','Existencias por encima del mínimo','check')}${kpi('Movimientos',db.movements.length,'registros','Entradas y salidas trazables','flow')}</div>`+toolbar('Buscar material o código…',['Disponible','Bajo mínimo'])+`<section class="panel" id="results">${materialsTable()}</section>`+`<section class="panel section-gap"><div class="panel-head"><h2>Últimos movimientos</h2></div><div class="activity">${db.movements.slice(0,8).map(m=>`<div class="activity-item">${esc(db.materials.find(x=>x.id===m.material)?.name)} · ${m.amount>0?'+':''}${num(m.amount)} · ${esc(m.reason)}<small>${date(m.at)} · Área de producción</small></div>`).join('')||'<p class="panel-subtitle">Los nuevos movimientos de inventario aparecerán aquí.</p>'}</div></section>`;}
function incidentsTable(){const list=db.incidents.filter(i=>matches(i.id,i.order,i.type,i.description,i.owner)&&(!statusFilter||i.status===statusFilter));return `<div class="table-wrap"><table><thead><tr><th>INCIDENCIA / ORDEN</th><th>TIPO Y DESCRIPCIÓN</th><th>SEVERIDAD</th><th>RESPONSABLE</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td><strong>${i.id}</strong><small>${i.order}</small></td><td><strong>${esc(i.type)}</strong><small style="white-space:normal;max-width:300px;line-height:1.6">${esc(i.description)}</small></td><td>${priority(i.severity)}</td><td>${esc(i.owner)}</td><td><span class="tag ${i.status==='Resuelta'?'s3':'danger'}">${esc(i.status)}</span></td><td><button class="btn small" data-action="edit-incident" data-id="${i.id}">Gestionar →</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No hay incidencias para esta búsqueda.</div></td></tr>'}</tbody></table></div>`;}
function incidentsView(){return heading('Gestión de incidencias','Registra lo ocurrido. Asigna una solución. Conserva la evidencia.',button('Registrar incidencia','new-incident'))+toolbar('Buscar incidencia, orden o responsable…',['Abierta','En atención','Resuelta'])+`<section class="panel" id="results">${incidentsTable()}</section>`;}
function reportOrders(){return db.orders.filter(o=>(!reportFrom||o.created>=reportFrom)&&(!reportTo||o.created<=reportTo));}
function reportsView(){const rows=reportOrders(),closed=rows.filter(o=>o.state>=3),onTime=closed.filter(o=>o.closed&&o.closed<=o.due),pairs=rows.reduce((a,o)=>a+o.quantity,0),ids=new Set(rows.map(o=>o.id)),inc=db.incidents.filter(i=>ids.has(i.order)),resolved=inc.filter(i=>i.status==='Resuelta');return heading('Reportes y control','Indicadores calculados a partir de tus registros de producción.',button('Imprimir / PDF','print','down','')+button('Exportar CSV','export-report','down'))+`<div class="toolbar"><div class="filters"><label class="field">Creación desde<input id="report-from" type="date" value="${reportFrom}"></label><label class="field">Hasta<input id="report-to" type="date" value="${reportTo}"></label><button class="btn" data-action="filter-report">Aplicar período</button><button class="text-link" data-action="clear-report">Todo el historial</button></div><span class="result-count">${rows.length} órdenes en el período</span></div><div class="print-only"><p>Reporte SIGCP MANACO · ${date(today())} · ${reportFrom||'Inicio'} a ${reportTo||'hoy'} · ${db.mode==='demo'?'Datos de demostración':'Datos locales'}</p></div><div class="kpis">${kpi('Volumen planificado',num(pairs),'pares','Suma de cantidades del período','box')}${kpi('Órdenes finalizadas',closed.length,'de '+rows.length,'Terminadas o despachadas','check')}${kpi('Cumplimiento de fechas',closed.length?Math.round(onTime.length/closed.length*100)+'%':'—','',closed.length?'Órdenes terminadas en fecha / cerradas':'No medido · sin órdenes cerradas','clock')}${kpi('Incidencias resueltas',inc.length?Math.round(resolved.length/inc.length*100)+'%':'—','',`${resolved.length} de ${inc.length} incidencias del período`,'alert')}</div><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Distribución por estado</h2></div><div class="report-list">${states.map((s,i)=>`<div class="report-row"><span>${s}</span><strong>${rows.filter(o=>o.state===i).length} órdenes</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Lectura operativa</h2></div><div class="report-list"><div class="report-row"><span>Órdenes vencidas del período</span><strong>${rows.filter(o=>o.state<3&&o.due<today()).length}</strong></div><div class="report-row"><span>Materiales bajo mínimo · inventario actual</span><strong>${lowStock().length}</strong></div><div class="report-row"><span>Tiempo medio de resolución</span><strong>${resolved.length?num(resolved.reduce((sum,i)=>sum+(new Date(i.closed)-new Date(i.created))/86400000,0)/resolved.length)+' días':'No medido'}</strong></div><div class="report-row"><span>Exactitud física de inventario</span><strong>No medido</strong></div><div class="report-row"><span>Adopción de usuarios</span><strong>No medido</strong></div></div></section></div><section class="panel section-gap"><div class="panel-head table-heading"><h2>Detalle de órdenes del período</h2></div>${orderTable(rows)}</section>`;}
const pilotItems=['Alcance del piloto aprobado','Usuarios y responsables definidos','Productos y materiales iniciales depurados','Órdenes de prueba seleccionadas','Casos de prueba ejecutados','Defectos críticos resueltos','Accesos y respaldos verificados','Usuarios capacitados','Indicadores y metas definidos','Decisión de continuidad documentada'];
function projectView(){const costs=[['Análisis y requerimientos',4000],['Diseño del sistema',4500],['Desarrollo del sistema',12000],['Pruebas y correcciones',3500],['Implementación y configuración',3000],['Capacitación',1500],['Infraestructura',2500],['Documentación',1000],['Contingencia',2500]];return heading('Proyecto y piloto','Marco de implementación y criterios de aceptación del informe.')+`<div class="note">Propuesta académica · ULAT 2026. El presupuesto es referencial y requiere validación con MANACO. Esta lista registra evidencias; no sustituye la aprobación del comité responsable.</div><div class="guide-grid">${[['01','Semanas 1–2','Diagnóstico y requerimientos','Proceso, actores, historias priorizadas y alcance aprobado.'],['02','Semanas 3–4','Diseño funcional y visual','Interfaces, modelo de datos y reglas de estados validadas.'],['03','Semanas 5–6','Desarrollo e integración','Productos, materiales, órdenes, seguimiento, incidencias y reportes.'],['04','Semanas 7–8','Pruebas, piloto y cierre','Capacitación, ejecución del piloto y evaluación de resultados.']].map(s=>`<article class="guide-card"><span class="step-number">S${s[0]}</span><div class="eyebrow">${s[1]}</div><h3>${s[2]}</h3><p>${s[3]}</p></article>`).join('')}</div><div class="report-grid section-gap"><section class="panel"><div class="panel-head"><h2>Preparación del piloto</h2><span class="tag s1">${Object.values(db.pilot).filter(x=>x.checked).length} / 10</span></div><div class="report-list">${pilotItems.map((item,i)=>`<div class="check-row"><span>${db.pilot[i]?.checked?icon('check'):icon('clock')}</span><div style="flex:1">${item}<small>${esc(db.pilot[i]?.evidence||'Pendiente de validar')}</small></div><button class="text-link" data-action="pilot" data-id="${i}">Registrar</button></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Presupuesto referencial</h2><span class="tag s0">BOB</span></div><div class="report-list">${costs.map(c=>`<div class="report-row"><span>${c[0]}</span><strong>Bs ${num(c[1])}</strong></div>`).join('')}<div class="report-row"><span>Total estimado</span><strong>Bs 34.500</strong></div><p class="panel-subtitle">Línea base: Bs 32.000 · Contingencia: Bs 2.500<br>Costos reales y beneficios: no medidos.</p></div></section></div>`;}
function settingsView(){return heading('Datos y respaldo','Mantén una copia de tus registros y conserva su trazabilidad.')+`<div class="note">Los datos se almacenan en este navegador y dispositivo. Los cambios no se comparten entre usuarios. Exporta respaldos periódicos; borrar los datos del navegador elimina los registros locales.</div><div class="guide-grid"><article class="guide-card"><span class="step-number">${icon('down')}</span><h3>Respaldo completo</h3><p>Descarga productos, recetas, materiales, movimientos, órdenes, incidencias, evidencias y bitácora en un archivo JSON.</p>${button('Descargar respaldo','backup','down','navy')}</article><article class="guide-card"><span class="step-number">${icon('shield')}</span><h3>Restaurar información</h3><p>Importa un respaldo de SIGCP. Se validarán los datos antes de mostrar un resumen y pedir la sustitución de los registros actuales.</p><label class="btn" for="restore-file">Seleccionar respaldo JSON</label><input id="restore-file" type="file" accept="application/json,.json" hidden></article></div><section class="panel section-gap"><div class="panel-head"><h2>Bitácora de actividad</h2><span class="tag s1">${db.audit.length} eventos</span></div><div class="activity">${db.audit.slice(0,30).map(a=>`<div class="activity-item">${esc(a.text)}<small>${date(a.at)} · ${esc(a.actor)}</small></div>`).join('')}</div></section><section class="guide-card section-gap"><h3>Entorno actual: ${db.mode==='demo'?'demostración':'registros propios'}</h3><p>Los datos iniciales son ficticios. Puedes comenzar con un registro vacío o volver a cargar los ejemplos. Estas acciones requieren confirmación.</p><div class="row-actions">${button('Comenzar sin datos','clear-data','plus','')}${button('Restablecer demostración','reset-demo','flow','')}</div></section>`;}
function guideView(){return heading('Guía de uso','Un circuito de información, desde los materiales hasta la entrega.')+`<div class="guide-grid">${[['01','Prepara el catálogo','Registra primero los materiales con su unidad, existencia y mínimo. Después crea los productos, sus tallas y su receta de consumo por par.'],['02','Planifica una orden','Selecciona producto y talla, cantidad de pares, fechas, prioridad y responsable. La orden comienza en estado Pendiente.'],['03','Inicia la producción','Abre la orden y avanza de estado. El sistema verifica la receta completa y descuenta los materiales una sola vez. Si faltan existencias, registra una entrada en Materiales.'],['04','Controla calidad e incidencias','Lleva la orden a Control de calidad. Registra fallas y asigna responsables. Para terminar, resuelve todas sus incidencias y escribe evidencia de calidad; luego podrás despachar.'],['05','Consulta y exporta','Filtra órdenes y reportes. Exporta los registros a CSV o utiliza Imprimir / PDF para generar un documento con el diálogo del navegador.'],['06','Respalda el trabajo','En Datos y respaldo descarga un JSON. Puedes restaurarlo tras revisar el resumen. La bitácora conserva las acciones realizadas en este dispositivo.']].map(s=>`<article class="guide-card"><span class="step-number">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div><div class="note section-gap">Alcance de esta versión: aplicación estática local en HTML, CSS y JavaScript. Para operación multiusuario se requiere un backend con autenticación, permisos, base de datos y respaldos de servidor. No se simula un inicio de sesión seguro.</div>`;}
function showModal(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
const field = (label,name,value='',type='text',extra='',full=false) => `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const selectField=(label,name,values,current='',full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}" required>${values.map(v=>{const pair=Array.isArray(v)?v:[v,v];return `<option value="${esc(pair[0])}" ${String(pair[0])===String(current)?'selected':''}>${esc(pair[1])}</option>`;}).join('')}</select></label>`;
const textarea=(label,name,value='',required=true)=>`<label class="field full">${label}<textarea name="${name}" maxlength="1000" ${required?'required':''}>${esc(value)}</textarea></label>`;
function formHTML(content,label='Guardar registro'){return `<form id="record-form"><div class="form-grid">${content}</div><div class="form-error" id="form-error" role="alert"></div><div class="form-footer"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary" type="submit">${label} ${icon('check')}</button></div></form>`;}
function bindForm(handler){$('#record-form').addEventListener('submit',e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));handler(data);}catch(error){$('#form-error').textContent=error.message;}});}
const nextId=(prefix,list)=>prefix+String(Math.max(0,...list.map(x=>Number(x.id.split('-')[1])||0))+1).padStart(3,'0');
function requiredText(value,label){const s=String(value||'').trim();if(!s)throw Error(label+' es obligatorio.');return s;}
function positive(value,label,integer=false,zero=false){const n=Number(value);if(!Number.isFinite(n)||(zero?n<0:n<=0)||(integer&&!Number.isInteger(n)))throw Error(label+' debe ser '+(zero?'un número no negativo':'mayor que cero')+(integer?' y entero':'')+'.');return n;}
function complete(message){log(message);persist(message);closeModal();render();}
function orderForm(){if(!db.products.length){toast('Registra un producto antes de crear órdenes.');location.hash='products';return;}showModal('Nueva orden de producción',formHTML(selectField('Producto','product',db.products.map(p=>[p.id,p.name]))+selectField('Talla','size',db.products[0].sizes.split(',').map(s=>s.trim()))+field('Cantidad de pares','quantity',100,'number','min="1" max="1000000" step="1" required')+selectField('Prioridad','priority',['Normal','Alta'])+field('Fecha de inicio','start',today(),'date','required')+field('Fecha de entrega','due',shiftDate(7),'date','required')+field('Responsable','owner','','text','required maxlength="80"',true),'Crear orden'));
 $('[name=product]').addEventListener('change',e=>{$('[name=size]').innerHTML=product(e.target.value).sizes.split(',').map(s=>`<option>${esc(s.trim())}</option>`).join('');});
 bindForm(d=>{if(d.due<d.start)throw Error('La entrega no puede ser anterior al inicio.');const p=product(d.product);if(!p||!p.sizes.split(',').map(x=>x.trim()).includes(d.size))throw Error('Selecciona una talla válida.');const o={id:nextId('OP-',db.orders),product:d.product,size:d.size,quantity:positive(d.quantity,'La cantidad',true),priority:d.priority,start:d.start,due:d.due,owner:requiredText(d.owner,'El responsable'),state:0,created:today(),closed:'',evidence:'',consumed:false,history:[{at:new Date().toISOString(),text:'Orden creada',actor:'Área de producción'}]};db.orders.push(o);complete(o.id+' creada correctamente');});}
function availability(o){return (product(o.product)?.bom||[]).map(b=>{const m=db.materials.find(m=>m.id===b.material);return {m,needed:Math.round(b.qty*o.quantity*10000)/10000,ok:!!m&&m.stock+1e-8>=b.qty*o.quantity};});}
function detail(id){const o=db.orders.find(o=>o.id===id);if(!o)return;const related=db.incidents.filter(i=>i.order===id&&i.status!=='Resuelta'),requirements=availability(o);showModal('Orden '+o.id,`<div class="row-actions">${badge(o.state)}${priority(o.priority)}</div><div class="detail-grid"><div><small>Producto / talla</small><strong>${esc(product(o.product)?.name)} · ${esc(o.size)}</strong></div><div><small>Cantidad</small><strong>${num(o.quantity)} pares</strong></div><div><small>Responsable</small><strong>${esc(o.owner)}</strong></div><div><small>Inicio → entrega</small><strong>${date(o.start)} → ${date(o.due)}</strong></div></div><div class="stepper">${states.map((s,i)=>`<div class="${i<=o.state?'done':''}">${s}</div>`).join('')}</div>${related.length?`<div class="note danger">${related.length} incidencia(s) pendiente(s). Deben resolverse antes de terminar la orden.</div>`:''}${o.state===0?`<h3>Materiales necesarios</h3><div class="report-list" style="padding:0">${requirements.map(r=>`<div class="report-row"><span>${esc(r.m?.name||'Material no disponible')}</span><strong style="color:var(--${r.ok?'green':'red'})">${num(r.needed)} / ${num(r.m?.stock||0)} ${esc(r.m?.unit)}</strong></div>`).join('')||'<p class="note danger">El producto no tiene receta. Edítalo antes de iniciar.</p>'}</div>`:''}${o.evidence?`<div class="note">Evidencia de calidad: ${esc(o.evidence)}</div>`:''}<h3 class="section-gap">Trazabilidad</h3><div class="activity">${o.history.map(h=>`<div class="activity-item">${esc(h.text)}<small>${date(h.at)} · ${esc(h.actor)}</small></div>`).join('')}</div><div class="form-footer"><button class="btn" data-action="incident-order" data-id="${o.id}" ${o.state>=3?'disabled':''}>Registrar incidencia</button>${o.state<4?`<button class="btn primary" data-action="advance" data-id="${o.id}">${['Iniciar producción','Enviar a calidad','Terminar orden','Registrar despacho'][o.state]} ${icon('arrow')}</button>`:''}</div>`);}
function advance(id){const o=db.orders.find(o=>o.id===id);if(!o||o.state>=4)return;
 if(o.state===0){const req=availability(o);if(!req.length){toast('Define la receta del producto antes de iniciar.');return;}if(req.some(r=>!r.ok)){toast('Materiales insuficientes. Registra una entrada en inventario.');return;}req.forEach(r=>{r.m.stock=Math.round((r.m.stock-r.needed)*10000)/10000;db.movements.unshift({id:nextId('MOV-',db.movements),material:r.m.id,amount:-r.needed,reason:'Consumo de '+o.id,at:new Date().toISOString()});});o.consumed=true;}
 if(o.state===2){if(db.incidents.some(i=>i.order===id&&i.status!=='Resuelta')){toast('Resuelve las incidencias de esta orden antes de terminar.');return;}closeModal();showModal('Control de calidad · '+id,formHTML(textarea('Evidencia de aprobación y cierre','evidence'),'Aprobar y terminar'));bindForm(d=>{o.evidence=requiredText(d.evidence,'La evidencia');o.closed=today();finishAdvance(o);closeModal();detail(id);});return;}
 finishAdvance(o);closeModal();detail(id);
}
function finishAdvance(o){o.state++;o.history.push({at:new Date().toISOString(),text:'Estado actualizado: '+states[o.state],actor:'Área de producción'});log(o.id+' → '+states[o.state]);persist('Orden actualizada a '+states[o.state]);render();}
function productForm(id){const p=db.products.find(p=>p.id===id);showModal(p?'Editar producto':'Nuevo producto',formHTML(field('Nombre del modelo','name',p?.name,'text','required maxlength="80"')+selectField('Categoría','category',['Formal','Casual','Deportivo','Escolar','Industrial'],p?.category)+field('Tallas (separadas por comas)','sizes',p?.sizes||'38, 39, 40, 41, 42','text','required maxlength="100"')+field('Color','color',p?.color,'text','required maxlength="40"')+textarea('Características','description',p?.description||'',false)+`<div class="field full"><span>Receta de materiales · consumo por par</span><small>Indica 0 para los materiales que no utiliza. Al menos uno es obligatorio.</small></div>`+db.materials.map(m=>field(esc(m.name)+' ('+esc(m.unit)+')','bom_'+m.id,p?.bom.find(b=>b.material===m.id)?.qty||0,'number','min="0" step="0.0001"')).join('')));
 bindForm(d=>{const name=requiredText(d.name,'El nombre');if(db.products.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))throw Error('Ya existe un producto con este nombre.');const sizes=[...new Set(d.sizes.split(',').map(s=>s.trim()).filter(Boolean))];if(!sizes.length||sizes.some(s=>!/^\d{1,2}(\.5)?$/.test(s)))throw Error('Usa tallas numéricas separadas por comas, por ejemplo: 38, 39, 40.');const bom=db.materials.map(m=>({material:m.id,qty:positive(d['bom_'+m.id],'El consumo',false,true)})).filter(b=>b.qty>0);if(!bom.length)throw Error('Define al menos un material con consumo mayor que cero.');if(p&&db.orders.some(o=>o.product===id&&o.state===0&&!sizes.includes(o.size)))throw Error('Hay órdenes pendientes que utilizan una talla que intentas quitar.');const value={id:p?.id||nextId('PRD-',db.products),name,category:d.category,sizes:sizes.join(', '),color:requiredText(d.color,'El color'),description:d.description.trim(),tone:p?.tone||'#365b83',bom};if(p)Object.assign(p,value);else db.products.push(value);complete('Producto '+value.id+' guardado');});}
function materialForm(id){const m=db.materials.find(m=>m.id===id);showModal(m?'Editar material':'Nuevo material',formHTML(field('Nombre del material','name',m?.name,'text','required maxlength="80"',true)+selectField('Unidad de medida','unit',['m²','pares','litros','kg','unidades','metros'],m?.unit)+field('Nivel mínimo','min',m?.min||0,'number','required min="0" step="0.0001"')+(!m?field('Existencia inicial','stock',0,'number','required min="0" step="0.0001"',true):'<div class="note field full">Para modificar existencias utiliza Movimiento. La unidad de un material utilizado en recetas no puede cambiarse.</div>')));bindForm(d=>{const name=requiredText(d.name,'El nombre');if(db.materials.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))throw Error('Ya existe un material con este nombre.');if(m&&m.unit!==d.unit&&(db.products.some(p=>p.bom.some(b=>b.material===id))||db.movements.some(x=>x.material===id)))throw Error('Este material está en uso. Conserva su unidad o registra uno nuevo.');const value={id:m?.id||nextId('MAT-',db.materials),name,unit:d.unit,min:positive(d.min,'El mínimo',false,true),stock:m?m.stock:positive(d.stock,'La existencia',false,true)};if(m)Object.assign(m,value);else db.materials.push(value);complete('Material '+value.id+' guardado');});}
function stockForm(id){const m=db.materials.find(m=>m.id===id);showModal('Movimiento de inventario',formHTML(`<div class="note field full">${esc(m.name)} · Existencia actual: ${num(m.stock)} ${esc(m.unit)}</div>`+selectField('Tipo de movimiento','type',['Entrada','Salida'])+field('Cantidad ('+esc(m.unit)+')','quantity','','number','min="0.0001" step="0.0001" required')+textarea('Motivo / referencia del movimiento','reason')));bindForm(d=>{let amount=positive(d.quantity,'La cantidad')*(d.type==='Salida'?-1:1);if(m.stock+amount<0)throw Error('La salida supera las existencias disponibles.');const reason=requiredText(d.reason,'El motivo');m.stock=Math.round((m.stock+amount)*10000)/10000;db.movements.unshift({id:nextId('MOV-',db.movements),material:id,amount,reason,at:new Date().toISOString()});complete('Movimiento registrado en '+m.name);});}
function incidentForm(id,orderId){const i=db.incidents.find(x=>x.id===id);const orders=db.orders.filter(o=>o.state<3||o.id===i?.order);if(!orders.length){toast('Necesitas una orden activa para registrar incidencias.');return;}showModal(i?'Gestionar '+i.id:'Registrar incidencia',formHTML(selectField('Orden relacionada','order',orders.map(o=>[o.id,o.id+' · '+product(o.product)?.name]),i?.order||orderId)+selectField('Tipo de incidencia','type',['Falla de máquina','Falta de material','Problema de calidad','Otra'],i?.type)+selectField('Severidad','severity',['Media','Alta','Baja'],i?.severity)+field('Responsable de atención','owner',i?.owner,'text','required maxlength="80"')+textarea('Descripción de lo ocurrido','description',i?.description||'')+(i?selectField('Estado','status',['Abierta','En atención','Resuelta'],i.status,true)+textarea('Acción y evidencia de resolución','action',i.action,false):'')));
 bindForm(d=>{if(i&&db.orders.find(o=>o.id===i.order)?.state>=3&&d.status!=='Resuelta')throw Error('Una incidencia de una orden cerrada no puede reabrirse.');if(i&&d.order!==i.order)throw Error('La orden de una incidencia existente no puede cambiarse.');if(i&&d.status==='Resuelta'&&!d.action.trim())throw Error('Describe la acción realizada antes de resolver la incidencia.');const value={id:i?.id||nextId('INC-',db.incidents),order:d.order,type:d.type,severity:d.severity,owner:requiredText(d.owner,'El responsable'),description:requiredText(d.description,'La descripción'),status:d.status||'Abierta',created:i?.created||today(),closed:d.status==='Resuelta'?(i?.closed||today()):'',action:d.action?.trim()||''};if(i)Object.assign(i,value);else db.incidents.unshift(value);complete(value.id+' guardada');});}
function pilotForm(id){const item=db.pilot[id];showModal('Evidencia del piloto',formHTML(`<div class="note field full">${pilotItems[id]}</div>`+selectField('Estado','status',['Pendiente','Validado'],item?.checked?'Validado':'Pendiente',true)+textarea('Evidencia / referencia documental','evidence',item?.evidence||'')));bindForm(d=>{db.pilot[id]={checked:d.status==='Validado',evidence:requiredText(d.evidence,'La evidencia'),at:new Date().toISOString()};complete('Criterio de piloto actualizado');});}
function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(filename,headers,rows){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download(filename+'-'+today()+'.csv','\uFEFF'+[headers,...rows].map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Archivo CSV exportado');}
function exportOrders(rows){csv('ordenes-manaco',['Orden','Producto','Talla','Pares','Estado','Prioridad','Inicio','Entrega','Responsable','Fecha de cierre','Evidencia'],rows.map(o=>[o.id,product(o.product)?.name,o.size,o.quantity,states[o.state],o.priority,o.start,o.due,o.owner,o.closed,o.evidence]));}
function validateBackup(data){
 const fail=()=>{throw Error('El archivo no es un respaldo válido de SIGCP o contiene relaciones inconsistentes.');};
 const str=v=>typeof v==='string'&&v.length<=5000;
 const day=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v));
 const timestamp=v=>str(v)&&!isNaN(Date.parse(v));
 const amount=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0;
 const listKeys=['products','materials','orders','incidents','audit','movements'];
 if(!data||data.version!==1||!['demo','own'].includes(data.mode)||!listKeys.every(k=>Array.isArray(data[k])&&data[k].length<=50000)||!data.pilot||typeof data.pilot!=='object'||Array.isArray(data.pilot))fail();
 for(const key of ['products','materials','orders','incidents','movements']){const ids=data[key].map(x=>x?.id);if(ids.some(id=>typeof id!=='string'||! /^(PRD|MAT|OP|INC|MOV)-\d+$/.test(id))||new Set(ids).size!==ids.length)fail();}
 const materialIds=new Set(data.materials.map(m=>m.id)),productIds=new Set(data.products.map(p=>p.id)),orderIds=new Set(data.orders.map(o=>o.id));
 if(data.materials.some(m=>!str(m.name)||!['m²','pares','litros','kg','unidades','metros'].includes(m.unit)||!amount(m.stock)||!amount(m.min)))fail();
 if(data.products.some(p=>![p.name,p.category,p.sizes,p.color,p.description].every(str)||!/^#[0-9a-f]{6}$/i.test(p.tone)||!Array.isArray(p.bom)||new Set(p.bom.map(b=>b.material)).size!==p.bom.length||p.bom.some(b=>!materialIds.has(b.material)||!amount(b.qty)||b.qty<=0)))fail();
 if(data.orders.some(o=>!productIds.has(o.product)||![o.size,o.owner,o.evidence].every(str)||!Number.isInteger(o.quantity)||o.quantity<=0||!Number.isInteger(o.state)||o.state<0||o.state>4||!['Normal','Alta'].includes(o.priority)||![o.start,o.due,o.created].every(day)||o.due<o.start||(o.closed&&!day(o.closed))||(o.state>=3&&(!o.closed||!o.evidence.trim()))||typeof o.consumed!=='boolean'||o.consumed!==(o.state>0)||!Array.isArray(o.history)||o.history.some(h=>!timestamp(h.at)||!str(h.text)||!str(h.actor))))fail();
 if(data.incidents.some(i=>!orderIds.has(i.order)||![i.type,i.description,i.owner,i.action].every(str)||!['Baja','Media','Alta'].includes(i.severity)||!['Abierta','En atención','Resuelta'].includes(i.status)||!day(i.created)||(i.closed&&!day(i.closed))||(i.status==='Resuelta'&&(!i.closed||!i.action.trim()))||(i.status!=='Resuelta'&&data.orders.find(o=>o.id===i.order).state>=3)))fail();
 if(data.movements.some(m=>!materialIds.has(m.material)||typeof m.amount!=='number'||!Number.isFinite(m.amount)||!str(m.reason)||!timestamp(m.at)))fail();
 if(data.audit.some(a=>!timestamp(a.at)||!str(a.text)||!str(a.actor)))fail();
 if(Object.entries(data.pilot).some(([key,p])=>!/^\d$/.test(key)||!p||typeof p.checked!=='boolean'||!str(p.evidence)||!timestamp(p.at)))fail();
 return data;
}
async function restore(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error('El respaldo supera el límite de 10 MB.');const imported=validateBackup(JSON.parse(await file.text()));showModal('Restaurar respaldo',`<div class="note">Se sustituirán los registros actuales con ${imported.products.length} productos, ${imported.materials.length} materiales, ${imported.orders.length} órdenes y ${imported.incidents.length} incidencias. Descarga un respaldo de los datos actuales antes de continuar.</div><div class="form-footer"><button class="btn" data-action="backup">Respaldar datos actuales</button><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="confirm-restore">Restaurar datos</button></div>`);$('#confirm-restore').onclick=()=>{const previous=db, previousIssue=storageIssue;db=imported;storageIssue=false;log('Respaldo restaurado');if(!persist('Respaldo restaurado correctamente')){db=previous;storageIssue=previousIssue;return;}closeModal();render();};}catch(error){toast(error.message==='Unexpected token'?'No se pudo leer el archivo JSON.':error.message);}}
function resetData(demo){showModal(demo?'Restablecer demostración':'Comenzar sin datos',`<div class="note danger">Esta acción sustituirá todos los datos guardados en este navegador. Exporta un respaldo si deseas conservarlos.</div><div class="form-footer"><button class="btn" data-action="backup">Descargar respaldo</button><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="confirm-reset">${demo?'Cargar demostración':'Comenzar sin datos'}</button></div>`);$('#confirm-reset').onclick=()=>{storageIssue=false;db=demo?seed():{version:1,mode:'own',products:[],materials:[],orders:[],incidents:[],movements:[],audit:[],pilot:{}};log(demo?'Demostración restablecida':'Registro vacío iniciado');persist('Entorno actualizado');closeModal();render();};}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;const handlers={'new-order':orderForm,'new-product':()=>productForm(),'edit-product':()=>productForm(id),'new-material':()=>materialForm(),'edit-material':()=>materialForm(id),stock:()=>stockForm(id),detail:()=>detail(id),advance:()=>advance(id),'new-incident':()=>incidentForm(),'edit-incident':()=>incidentForm(id),'incident-order':()=>{closeModal();incidentForm(null,id);},close:closeModal,pilot:()=>pilotForm(id),'recover-raw':()=>download('recuperacion-manaco-'+today()+'.txt',unreadableData,'text/plain'),backup:()=>{download('respaldo-manaco-'+today()+'.json',JSON.stringify(db,null,2),'application/json');toast('Respaldo descargado');},'export-orders':()=>exportOrders(route==='orders'?filteredOrders():db.orders),'export-materials':()=>csv('materiales-manaco',['Código','Material','Existencia','Mínimo','Unidad'],db.materials.map(m=>[m.id,m.name,m.stock,m.min,m.unit])),'export-report':()=>exportOrders(reportOrders()),print:()=>window.print(),'filter-report':()=>{const from=$('#report-from').value,to=$('#report-to').value;if(from&&to&&from>to){toast('La fecha inicial no puede ser posterior a la final.');return;}reportFrom=from;reportTo=to;render();},'clear-report':()=>{reportFrom='';reportTo='';render();},'clear-data':()=>resetData(false),'reset-demo':()=>resetData(true)};handlers[action]?.();});
function updateResults(){const html={orders:()=>orderTable(filteredOrders()),products:productCards,materials:materialsTable,incidents:incidentsTable}[route];if(html)$('#results').innerHTML=html();}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;updateResults();}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){statusFilter=e.target.value;updateResults();}if(e.target.id==='restore-file')restore(e.target.files[0]);});
$('#close-modal').onclick=closeModal;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#menu-toggle').onclick=()=>{const open=$('#sidebar').classList.toggle('is-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));};
document.addEventListener('click',e=>{if($('#sidebar').classList.contains('is-open')&&!e.target.closest('.sidebar')&&!e.target.closest('#menu-toggle')){$('#sidebar').classList.remove('is-open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{query='';statusFilter='';$('#sidebar').classList.remove('is-open');$('#menu-toggle').setAttribute('aria-expanded','false');if($('#modal').open)closeModal();render();window.scrollTo(0,0);});
$('#notification').innerHTML=icon('bell');$('#notification').onclick=()=>{showModal('Centro de atención',`<div class="alert-list">${alertsHTML()}</div><div class="form-footer"><button class="btn primary" data-action="close">Entendido</button></div>`);};
$('#plant-icon').innerHTML=icon('factory');
